update country_flag_history set label_fr = 'Principauté de Serbie', label_en = 'Principality of Serbia', notes_fr = 'Le tricolore rouge-bleu-blanc apparaît en 1835 avec la Constitution de Sretenje ; la principauté devient pleinement indépendante en 1878.', notes_en = 'The red-blue-white tricolour appeared in 1835 with the Sretenje Constitution; the principality became fully independent in 1878.' where id = 2475 and iso_code = 'rs';
update country_flag_history set label_fr = 'Royaume de Serbie', label_en = 'Kingdom of Serbia', notes_fr = 'Milan Obrenović se proclame roi en 1882 ; l''aigle bicéphale couronné figure sur le tricolore d''État.', notes_en = 'Milan Obrenović proclaimed himself king in 1882; the crowned double-headed eagle appeared on the state tricolour.' where id = 2476 and iso_code = 'rs';
update country_flag_history set label_fr = 'Serbie sous occupation allemande', label_en = 'German-occupied Serbia', notes_fr = 'Sous l''occupation allemande, le gouvernement collaborateur de Milan Nedić arbore le tricolore serbe.', notes_en = 'Under German occupation, Milan Nedić''s collaborationist government flew the Serbian tricolour.' where id = 2477 and iso_code = 'rs';
update country_flag_history set label_fr = 'République socialiste de Serbie', label_en = 'Socialist Republic of Serbia', notes_fr = 'Au sein de la Yougoslavie, la Serbie arbore le tricolore rouge-bleu-blanc frappé d''une étoile rouge.', notes_en = 'Within Yugoslavia, Serbia flew the red-blue-white tricolour bearing a red star.' where id = 2478 and iso_code = 'rs';
update country_flag_history set label_fr = 'République de Serbie (2004-2010)', label_en = 'Republic of Serbia (2004–2010)', notes_fr = 'Le tricolore retrouve les armoiries à l''aigle bicéphale ; leur dessin est modifié en 2010.', notes_en = 'The tricolour regained the double-headed eagle arms; their design was changed in 2010.' where id = 2479 and iso_code = 'rs';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('rs', '/flags/history/rs-1918.svg', '1918-12-01', '1941-04-17', 'Royaume des Serbes, Croates et Slovènes puis de Yougoslavie', 'Kingdom of Serbs, Croats and Slovenes, then Yugoslavia', 'Après 1918, la Serbie est le cœur du nouveau royaume, dont le tricolore bleu-blanc-rouge reprend les couleurs panslaves.', 'After 1918 Serbia was the core of the new kingdom, whose blue-white-red tricolour used the Pan-Slavic colours.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('rs', '/flags/history/rs-1945.svg', '1945-11-29', '1992-04-27', 'Yougoslavie socialiste', 'Socialist Yugoslavia', 'Drapeau de la Yougoslavie de Tito : le tricolore bleu-blanc-rouge frappé d''une étoile rouge bordée d''or.', 'Flag of Tito''s Yugoslavia: the blue-white-red tricolour bearing a gold-edged red star.');
